// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.personaimport android.Manifestimport android.content.pm.PackageManagerimport android.os.Bundleimport androidx.activity.ComponentActivityimport androidx.activity.compose.setContentimport androidx.activity.enableEdgeToEdgeimport androidx.activity.result.contract.ActivityResultContractsimport androidx.activity.viewModelsimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.paddingimport androidx.compose.material3.Scaffoldimport androidx.compose.runtime.collectAsStateimport androidx.compose.runtime.getValueimport androidx.compose.ui.Modifierimport androidx.core.content.ContextCompatimport androidx.core.splashscreen.SplashScreen.Companion.installSplashScreenimport androidx.fragment.app.FragmentActivityimport androidx.lifecycle.lifecycleScopeimport com.roshan.persona.di.AppInitializersimport com.roshan.persona.ui.navigation.NousNavHostimport com.roshan.persona.ui.screens.AutomationRuleSummaryimport com.roshan.persona.ui.screens.PersonaSummaryimport com.roshan.persona.ui.screens.SkillCategoryimport com.roshan.persona.ui.screens.SkillSummaryimport com.roshan.persona.ui.state.NousViewModelimport com.roshan.persona.ui.theme.NousThemeimport dagger.hilt.android.AndroidEntryPointimport kotlinx.coroutines.launchimport timber.log.Timberimport javax.inject.Inject/** * NOUS — Single-activity entry point. * * All UI state and button callbacks are handled by [NousViewModel]. * This activity only provides the Activity context for biometric prompts * and permission requests. */@AndroidEntryPointclass MainActivity : FragmentActivity() {    @Inject    lateinit var appInitializers: AppInitializers    private val viewModel: NousViewModel by viewModels()    private val permissionLauncher = registerForActivityResult(        ActivityResultContracts.RequestMultiplePermissions()    ) { results ->        val granted = results.count { it.value }        val total = results.size        Timber.tag("NOUS.Permissions").i("Permissions granted: $granted/$total")    }    override fun onCreate(savedInstanceState: Bundle?) {        val splash = installSplashScreen()        super.onCreate(savedInstanceState)        enableEdgeToEdge()        try {            appInitializers.initializeAll(applicationContext)        } catch (e: IllegalStateException) {            Timber.tag("NOUS.Boot").e(e, "Critical initializer failed — entering safe mode")        }        splash.setKeepOnScreenCondition { false }        requestEssentialPermissions()        setContent {            NousTheme {                Scaffold(modifier = Modifier.fillMaxSize()) { innerPadding ->                    val uiState by viewModel.uiState.collectAsState()                    NousNavHost(                        stateProvider = viewModel.uiStateProvider,                        viewModel = viewModel,                        personas = uiState.personas.map { p ->                            PersonaSummary(p.id, p.displayName, p.tagline, p.archetype)                        },                        activePersonaId = uiState.activePersonaId,                        activePersonaName = uiState.activePersonaName,                        activePersonaTagline = uiState.activePersonaTagline,                        onPersonaSelected = { id -> viewModel.selectPersona(id) },                        skills = uiState.skills.map { s ->                            SkillSummary(                                id = s.id,                                displayName = s.displayName,                                category = SkillCategory.entries.firstOrNull { it.label == s.category }                                    ?: SkillCategory.System,                            )                        },                        automationRules = uiState.automationRules.map { r ->                            AutomationRuleSummary(r.id, r.name, r.triggerDescription, r.actionDescription, r.enabled)                        },                        onSkillClick = { skill -> viewModel.onSkillClick(skill.id) },                        onCreateAutomation = { viewModel.navigateTo("skills/create_automation") },                        onToggleAutomation = { rule -> viewModel.toggleAutomationRule(rule.id) },                        settingsGroups = getSettingsGroups(),                        onSettingsEntryClick = { entry -> viewModel.onSettingsEntryClick(entry.id) },                        isMicListening = uiState.isMicListening,                        onMicClick = { viewModel.toggleMic() },                        onCapture = { viewModel.onCapture() },                        onFlipCamera = { viewModel.onFlipCamera() },                        lastVisionResult = uiState.lastVisionResult,                        biometricAvailable = uiState.biometricAvailable,                        onBiometricUnlock = { viewModel.unlockWithBiometric(this) },                        onPinSubmit = { pin -> viewModel.unlockWithPin(pin) },                        onUsePasskey = { viewModel.usePasskey() },                        attemptsRemaining = uiState.attemptsRemaining,                        lockoutMs = uiState.lockoutMs,                        appVersion = uiState.appVersion,                        buildNumber = uiState.buildNumber,                        safeMode = uiState.safeMode,                        integrityVerified = uiState.integrityVerified,                        initProgress = uiState.initProgress,                        initStepDescription = uiState.initStep,                        onSplashFinished = { viewModel.onSplashFinished() },                        isLocked = uiState.isLocked,                        userName = "User",                        modifier = Modifier.padding(innerPadding),                    )                }            }        }    }    private fun requestEssentialPermissions() {        val permissions = arrayOf(            Manifest.permission.RECORD_AUDIO,            Manifest.permission.CAMERA,            Manifest.permission.READ_CONTACTS,            Manifest.permission.POST_NOTIFICATIONS,        )        val toRequest = permissions.filter {            ContextCompat.checkSelfPermission(this, it) != PackageManager.PERMISSION_GRANTED        }.toTypedArray()        if (toRequest.isNotEmpty()) {            permissionLauncher.launch(toRequest)        }    }    private fun getSettingsGroups(): List<com.roshan.persona.ui.screens.SettingsGroup> {        return listOf(            com.roshan.persona.ui.screens.SettingsGroup("Brain & Cognitive", listOf(                com.roshan.persona.ui.screens.SettingsEntry("persona_studio", "Persona Studio", "Choose and customize your AI persona"),                com.roshan.persona.ui.screens.SettingsEntry("cognitive", "Cognitive Engine", "Reasoning depth, planning, self-correction"),                com.roshan.persona.ui.screens.SettingsEntry("memory", "Memory Browser", "View episodic + semantic memory"),                com.roshan.persona.ui.screens.SettingsEntry("self_modify", "Self-Modify (Hacker)", "Rhino JS sandbox for custom scripts"),            )),            com.roshan.persona.ui.screens.SettingsGroup("LLM", listOf(                com.roshan.persona.ui.screens.SettingsEntry("llm_config", "LLM Configuration", "Local + cloud providers, budget"),            )),            com.roshan.persona.ui.screens.SettingsGroup("Voice", listOf(                com.roshan.persona.ui.screens.SettingsEntry("voice_config", "Voice Configuration", "STT, TTS, wake word, speaker ID"),            )),            com.roshan.persona.ui.screens.SettingsGroup("Vision", listOf(                com.roshan.persona.ui.screens.SettingsEntry("vision_config", "Camera & Detection", "OCR, objects, faces, barcodes"),            )),            com.roshan.persona.ui.screens.SettingsGroup("Connectivity", listOf(                com.roshan.persona.ui.screens.SettingsEntry("connectivity", "Calls & SMS", "Contacts, spam, recording, SOS"),            )),            com.roshan.persona.ui.screens.SettingsGroup("Security", listOf(                com.roshan.persona.ui.screens.SettingsEntry("app_lock", "App Lock", "Biometric + PIN + passkey"),                com.roshan.persona.ui.screens.SettingsEntry("vault", "Credential Vault", "Passwords, API keys, cards"),                com.roshan.persona.ui.screens.SettingsEntry("audit_log", "Audit Log", "90-day encrypted audit trail"),                com.roshan.persona.ui.screens.SettingsEntry("backup", "Backup & Restore", "Encrypted full-app backup"),                com.roshan.persona.ui.screens.SettingsEntry("privacy", "Privacy Settings", "Data collection, telemetry"),            )),            com.roshan.persona.ui.screens.SettingsGroup("Developer", listOf(                com.roshan.persona.ui.screens.SettingsEntry("logs", "Logs & Traces", "Real-time logcat viewer"),                com.roshan.persona.ui.screens.SettingsEntry("telemetry", "Telemetry", "OpenTelemetry config"),                com.roshan.persona.ui.screens.SettingsEntry("crash_markers", "Crash Markers", "Recent crash history"),            )),            com.roshan.persona.ui.screens.SettingsGroup("About", listOf(                com.roshan.persona.ui.screens.SettingsEntry("about", "About NOUS", "Version, license, strategy reference"),            )),        )    }    override fun onResume() {        super.onResume()        lifecycleScope.launch {            try {                viewModel.uiStateProvider.refreshBrainStats()                viewModel.uiStateProvider.refreshMemoryData()            } catch (e: Exception) {                Timber.tag("NOUS.UI").w(e, "Failed to refresh stats on resume")            }        }    }}